-- Re-runs the leaf-category re-parenting from
-- 20260908120001_group_clothing_categories, this time matching each
-- category's name case-insensitively (and ignoring leading/trailing
-- whitespace) instead of requiring an exact byte-for-byte match.
--
-- That earlier migration's 1,804 UPDATE statements each targeted one leaf
-- category by an EXACT (case-sensitive) name match. Real production data
-- can differ from the migration's hardcoded expected casing (e.g. a
-- category actually named "Sexy Underwear & Costumes" title-case did not
-- match the migration's "Sexy underwear & costumes" sentence-case), so on
-- any environment where a leaf category's stored name casing drifted from
-- what the original migration expected, that single UPDATE silently
-- affected zero rows -- the category was left flat (parentId NULL, not
-- promoted into any of the 51 groups), which the app's UI/Suggest logic
-- then read as a valid standalone leaf, one level shallower than intended.
--
-- Confirmed via scripts/diagnose-suggest-categories.js against a real
-- business (HXI Fashions): "Sexy Underwear & Costumes" was still
-- parentId=NULL on that database despite the grouping migration having run,
-- purely because of this casing mismatch.
--
-- Idempotent -- safe to re-run. The added "parentId" IS DISTINCT FROM
-- '<groupId>' guard also means rows already correctly parented (the
-- overwhelming majority, matched on the first migration's run) are true
-- no-ops here, not just same-value re-writes.

UPDATE business_categories SET "parentId" = 'abc2c92b-1215-4eb6-be71-3356c2b3d46b', "updatedAt" = NOW() WHERE "businessType" = 'clothing' AND LOWER(TRIM(name)) = LOWER(TRIM('3 Piece bikini set')) AND (id != 'abc2c92b-1215-4eb6-be71-3356c2b3d46b') AND ("parentId" IS DISTINCT FROM 'abc2c92b-1215-4eb6-be71-3356c2b3d46b');
UPDATE business_categories SET "parentId" = 'abc2c92b-1215-4eb6-be71-3356c2b3d46b', "updatedAt" = NOW() WHERE "businessType" = 'clothing' AND LOWER(TRIM(name)) = LOWER(TRIM('3 piece bikini sets')) AND (id != 'abc2c92b-1215-4eb6-be71-3356c2b3d46b') AND ("parentId" IS DISTINCT FROM 'abc2c92b-1215-4eb6-be71-3356c2b3d46b');
